// REDACTED_SECRET_PLACEHOLDER
// WF-07-A: Gate Evaluation Logic
// REDACTED_SECRET_PLACEHOLDER
// Inputs (from Postgres: Read All Flags):
//   item.json = {
//     case_id, documents_ready, kyc_ready, references_ready,
//     ra01_ready, ra02_ready, ra03_ready, ra04_ready, ra05_ready, ra06_ready,
//     required_inputs (JSONB array of strings), gate_triggered_at
//   }
//
// Output: passes item through with two extra fields:
//   allRequiredFlagsTrue  — boolean
//   gateAlreadyTriggered  — boolean
// REDACTED_SECRET_PLACEHOLDER

const row = $input.first().json;

// required_inputs arrives as a JS array (n8n parses JSONB automatically)
const requiredFlags = Array.isArray(row.required_inputs)
  ? row.required_inputs
  : JSON.parse(row.required_inputs || '[]');

if (requiredFlags.length === 0) {
  throw new Error(`case_id ${row.case_id}: required_inputs is empty — was Component B run at intake?`);
}

// Check every required flag is true on the current row
const allRequiredFlagsTrue = requiredFlags.every(flag => row[flag] === true);

// gate_triggered_at is null if the gate has never fired
const gateAlreadyTriggered = row.gate_triggered_at !== null && row.gate_triggered_at !== undefined;

// Emit diagnostic info for n8n execution log
console.log(JSON.stringify({
  case_id: row.case_id,
  requiredFlags,
  flagStates: requiredFlags.reduce((acc, f) => ({ ...acc, [f]: row[f] }), {}),
  allRequiredFlagsTrue,
  gateAlreadyTriggered
}));

return [{
  json: {
    ...row,
    allRequiredFlagsTrue,
    gateAlreadyTriggered
  }
}];

// Gate already triggered or race condition lost — silently do nothing.
// Log for diagnostics only.
console.log('WF-07-A: Gate not fired for case', $input.first().json.case_id, '— condition not met or already triggered.');
return [];

// Race condition: lock was obtained but another transaction already
// set gate_triggered_at before ours. Silent exit.
console.log('WF-07-A: Lost race condition lock for case', $input.first().json.case_id, '— gate already fired by concurrent transaction.');
return [];
